 void Drag(object sender,MouseEventArgs e){if(e.Button==MouseButtons.Left){ReleaseCapture();SendMessage(Handle,0xA1,(IntPtr)2,IntPtr.Zero);}}
 void Maximize(){MaximizedBounds=Screen.FromHandle(Handle).WorkingArea;WindowState=WindowState==FormWindowState.Maximized?FormWindowState.Normal:FormWindowState.Maximized;}
 static void Setup(DeckButton b,string text,string glyph,Color color){b.Text=text;b.Glyph=glyph;b.Fill=color;b.Dock=DockStyle.Fill;b.Margin=new Padding(0,0,8,0);}
 void LoadContacts(){var root=AppDomain.CurrentDomain.BaseDirectory;var folder=Path.Combine(root,"telefones");var metadata=Path.Combine(root,"telefones-contatos.json");try{if(File.Exists(metadata)){var data=new JavaScriptSerializer().DeserializeObject(File.ReadAllText(metadata)) as object[];if(data!=null)foreach(var entry in data){var d=entry as Dictionary<string,object>;if(d!=null&&d.ContainsKey("Id")&&d.ContainsKey("Name"))ReadContact(folder,Convert.ToString(d["Id"]),Convert.ToString(d["Name"]));}}if(contacts.Count==0&&Directory.Exists(folder))foreach(var f in Directory.GetFiles(folder,"*.txt")){string id=Path.GetFileNameWithoutExtension(f);ReadContact(folder,id,System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(id));}}catch(Exception e){status.Text=e.Message;}}
 void ReadContact(string folder,string id,string name){if(!System.Text.RegularExpressions.Regex.IsMatch(id??"",@"^[a-z]{2,24}$"))return;var file=Path.Combine(folder,id+".txt");if(File.Exists(file))contacts.Add(new Contact{Id=id,Name=name,Number=File.ReadAllText(file).Trim()});}
 string FavPath{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"favorites.local.json");}}
 void LoadFavorites(){try{if(File.Exists(FavPath))foreach(var id in new JavaScriptSerializer().Deserialize<string[]>(File.ReadAllText(FavPath)))favorites.Add(id);}catch{}}
 void SaveFavorites(){File.WriteAllText(FavPath,new JavaScriptSerializer().Serialize(favorites.ToArray()));}
 void SetTab(bool fav){favoritesOnly=fav;allTab.Fill=fav?DeckTheme.Bg:DeckTheme.Raised;favTab.Fill=fav?DeckTheme.Raised:DeckTheme.Bg;allTab.Invalidate();favTab.Invalidate();Filter();}
 void Filter(){var selected=list.SelectedItem as Contact;string query=search.Text.Trim();list.BeginUpdate();list.Items.Clear();foreach(var c in contacts)if((!favoritesOnly||favorites.Contains(c.Id))&&(c.Name.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0||c.Number.Contains(query)))list.Items.Add(c);if(selected!=null&&list.Items.Contains(selected))list.SelectedItem=selected;else if(list.Items.Count>0)list.SelectedIndex=0;list.EndUpdate();count.Text=list.Items.Count+" contatos  ·  ★ para favoritar";SelectContact();}
 void SelectContact(){var c=list.SelectedItem as Contact;selectedName.Text=c==null?"Escolha um contato":c.Name;selectedNumber.Text=c==null?"Busque por nome ou use o discador":c.Number;call.Enabled=c!=null&&!busy;}
 void DrawContact(object sender,DrawItemEventArgs e){if(e.Index<0)return;var c=(Contact)list.Items[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;var bounds=new Rectangle(e.Bounds.X,e.Bounds.Y,e.Bounds.Width-2,e.Bounds.Height-4);using(var p=DeckTheme.Round(bounds,8))using(var b=new SolidBrush(selected?Color.FromArgb(27,48,66):DeckTheme.Bg))e.Graphics.FillPath(b,p);var circle=new Rectangle(bounds.X+9,bounds.Y+10,36,36);using(var b=new SolidBrush(selected?DeckTheme.Blue:DeckTheme.Raised))e.Graphics.FillEllipse(b,circle);using(var f=new Font("Segoe UI",12,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,String.IsNullOrEmpty(c.Name)?"?":c.Name.Substring(0,1).ToUpper(),f,circle,DeckTheme.Text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);using(var f=new Font("Segoe UI Semibold",10))TextRenderer.DrawText(e.Graphics,c.Name,f,new Rectangle(bounds.X+56,bounds.Y+8,bounds.Width-87,24),DeckTheme.Text,TextFormatFlags.EndEllipsis);using(var f=new Font("Consolas",9))TextRenderer.DrawText(e.Graphics,c.Number,f,new Rectangle(bounds.X+56,bounds.Y+32,bounds.Width-87,20),DeckTheme.Dim,TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI Symbol",12))TextRenderer.DrawText(e.Graphics,favorites.Contains(c.Id)?"★":"☆",f,new Rectangle(bounds.Right-28,bounds.Y+16,24,25),favorites.Contains(c.Id)?Color.Gold:DeckTheme.Dim,TextFormatFlags.HorizontalCenter);}
 async void RunAction(string arguments,string success){if(busy)return;busy=true;call.Enabled=answer.Enabled=hangup.Enabled=false;status.Text="Enviando comando…";try{int exit=await Task.Run(()=>{using(var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,arguments){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=AppDomain.CurrentDomain.BaseDirectory})){p.WaitForExit();return p.ExitCode;}});if(!IsDisposed)status.Text=exit==0?success:"Comando não concluído. Confira o aviso do PhoneDeck.";}catch(Exception e){if(!IsDisposed)status.Text=e.Message;}finally{busy=false;if(!IsDisposed){answer.Enabled=hangup.Enabled=true;SelectContact();}}}
 async void RefreshAudio(){if(reading)return;reading=true;int started=generation;try{var state=await Task.Run(()=>new[]{AudioActions.Microphone(null,false),AudioActions.SpeakerLevel(null).ToString()});if(!IsDisposed&&started==generation){RenderMic(state[0]);int level=Int32.Parse(state[1]);if(!volume.Capture)volume.Value=level;volumeLabel.Text="Volume geral  ·  "+level+"%";CaptureWindow();}}catch{if(!IsDisposed){micState.Text="Áudio indisponível";micState.ForeColor=DeckTheme.Dim;mic.Enabled=false;}}finally{reading=false;}}
 void RenderMic(string state){bool muted=state.Contains("silenciado");micState.Text=muted?"●  Microfone silenciado":"●  Microfone ligado";micState.ForeColor=muted?DeckTheme.Red:DeckTheme.Green;mic.Text=muted?"Ativar microfone":"Silenciar microfone";mic.Fill=muted?Color.FromArgb(86,34,45):Color.FromArgb(23,70,57);mic.Ink=muted?DeckTheme.Red:DeckTheme.Green;mic.Enabled=true;mic.Invalidate();}
 void ResizeHistory(){if(recent.ClientSize.Width>100){int available=recent.ClientSize.Width-2;recent.Columns[0].Width=available/2;recent.Columns[1].Width=available-available/2;}}
 void SetVolume(){try{int level=AudioActions.SpeakerLevel(volume.Value);volumeLabel.Text="Volume geral  ·  "+level+"%";}catch(Exception e){status.Text=e.Message;}}
 async void SyncPhone(){if(syncing)return;syncing=true;sync.Enabled=false;try{int exit=await Task.Run(()=>{using(var p=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--snapshot"){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(14000)){p.Kill();return 3;}return p.ExitCode;}});if(IsDisposed)return;if(exit!=0){connection.Text="Leitura indisponível";return;}var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"phone-snapshot.local.json")));string name=Convert.ToString(data["Device"]),state=Convert.ToString(data["Connection"]);device.Text=name.Length>0?name:"Vincular ao Celular";connection.Text="●  "+state;connection.ForeColor=state.Equals("Conectado",StringComparison.OrdinalIgnoreCase)?DeckTheme.Green:DeckTheme.Dim;recent.Items.Clear();var rows=data["Recent"] as System.Collections.ArrayList;if(rows!=null)foreach(Dictionary<string,object> row in rows){var item=new ListViewItem(Convert.ToString(row["Name"]));item.SubItems.Add(Convert.ToString(row["Time"]).Replace("\u200e",""));recent.Items.Add(item);}ResizeHistory();syncLabel.Text=recent.Items.Count>0?"Histórico lido do celular  ·  "+DateTime.Now.ToString("HH:mm"):"Sem histórico acessível. Abra Chamadas no Vincular ao Celular e atualize.";captured=false;CaptureWindow();}catch{if(!IsDisposed)connection.Text="Leitura indisponível";}finally{syncing=false;if(!IsDisposed)sync.Enabled=true;}}
 void CaptureWindow(){if(capture&&!captured){captured=true;using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"phonedeck-window.local.png"));}}}
 void AddContactDialog(){using(var dialog=new Form{Text="Adicionar contato",ClientSize=new Size(380,235),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,StartPosition=FormStartPosition.CenterParent,BackColor=DeckTheme.Surface,ForeColor=DeckTheme.Text,Font=Font}){var name=new TextBox{BackColor=DeckTheme.Raised,ForeColor=DeckTheme.Text};var phone=new TextBox{BackColor=DeckTheme.Raised,ForeColor=DeckTheme.Text};Place(dialog,DeckTheme.Label("Nome",10,DeckTheme.Dim),22,15,330,24);Place(dialog,name,22,43,330,29);Place(dialog,DeckTheme.Label("Telefone com DDD",10,DeckTheme.Dim),22,86,330,24);Place(dialog,phone,22,114,330,29);var save=Button("Salvar contato","",DeckTheme.Blue);Place(dialog,save,22,170,330,42);save.Click+=(s,e)=>{if(name.Text.Trim().Length==0||!System.Text.RegularExpressions.Regex.IsMatch(phone.Text.Trim(),@"^(?:\+[1-9][0-9]{7,14}|[0-9]{8,14})$")){MessageBox.Show(dialog,"Preencha nome e telefone válido.","PhoneDeck");return;}try{string id="contato"+String.Concat(Guid.NewGuid().ToByteArray().Take(8).Select(v=>(char)('a'+v%26)));var root=AppDomain.CurrentDomain.BaseDirectory;Directory.CreateDirectory(Path.Combine(root,"telefones"));File.WriteAllText(Path.Combine(root,"telefones",id+".txt"),phone.Text.Trim());var path=Path.Combine(root,"telefones-contatos.json");var serializer=new JavaScriptSerializer();var rows=File.Exists(path)?serializer.Deserialize<List<Dictionary<string,object>>>(File.ReadAllText(path)):new List<Dictionary<string,object>>();rows.Add(new Dictionary<string,object>{{"Id",id},{"Name",name.Text.Trim()}});File.WriteAllText(path,serializer.Serialize(rows));contacts.Add(new Contact{Id=id,Name=name.Text.Trim(),Number=phone.Text.Trim()});Filter();dialog.Close();}catch(Exception ex){MessageBox.Show(dialog,ex.Message,"PhoneDeck");}};dialog.ShowDialog(this);}}
}



